From 8024193d4da49bc379d3ac0872e108bb9cdac45c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:03:13 +0100
Subject: [PATCH] applets/pager: show a desktop's windows on middle click

Middle-clicking a desktop in the pager did nothing, so seeing the windows
of another desktop meant switching to it first. Now it opens KWin's window
view with that desktop's windows, and the tooltip mentions this.

BUG: 524941
---
 applets/pager/qml/main.qml | 36 ++++++++++++++++++++++++++++++++++++
 1 file changed, 36 insertions(+)

diff --git a/applets/pager/qml/main.qml b/applets/pager/qml/main.qml
index b4211ddbbd..ed3f09480e 100644
--- a/applets/pager/qml/main.qml
+++ b/applets/pager/qml/main.qml
@@ -17,6 +17,7 @@ import org.kde.draganddrop as DnD
 import plasma.applet.org.kde.plasma.pager
 import org.kde.plasma.activityswitcher as ActivitySwitcher
 import org.kde.kirigami as Kirigami
+import org.kde.plasma.workspace.dbus as DBus

 import org.kde.kcmutils as KCM
 import org.kde.config as KConfig
@@ -90,6 +91,16 @@ PlasmoidItem {
         return text
     }

+    function activateWindowView(winIds: var): void {
+        DBus.SessionBus.asyncCall({service: "org.kde.KWin.Effect.WindowView1", path: "/org/kde/KWin/Effect/WindowView1", iface: "org.kde.KWin.Effect.WindowView1", member: "activate", arguments: [winIds.map(s => String(s))], signature: "(as)"});
+    }
+
+    DBus.DBusServiceWatcher {
+        id: effectWatcher
+        busType: DBus.BusType.Session
+        watchedService: "org.kde.KWin.Effect.WindowView1"
+    }
+
     MouseArea {
         id: rootMouseArea
         anchors.fill: parent
@@ -330,6 +341,17 @@ PlasmoidItem {
                 // it also gives us more flexibility when it comes to styling the <li>
                 textFormat: Text.RichText

+                function windowIds(): var {
+                    let winIds = []
+                    for (let i = 0, length = windowRectRepeater.count; i < length; ++i) {
+                        const window = windowRectRepeater.itemAt(i) as WindowDelegate
+                        if (window) {
+                            winIds = winIds.concat(window.winIdList)
+                        }
+                    }
+                    return winIds
+                }
+
                 function updateSubTextIfNeeded() {
                     if (!containsMouse) {
                         return;
@@ -370,6 +392,11 @@ PlasmoidItem {
                     }

                     if (text.length) {
+                        if (effectWatcher.registered) {
+                            text += "<br>" + (root.isActivityPager
+                                ? i18nc("@info:tooltip", "Middle-click to show the windows of this activity")
+                                : i18nc("@info:tooltip", "Middle-click to show the windows of this desktop"))
+                        }
                         // Get rid of the spacing <ul> would cause
                         text = "<style>ul { margin: 0; }</style>" + text
                     }
@@ -438,7 +465,15 @@ PlasmoidItem {
                     anchors.fill: parent
                     hoverEnabled: true
                     activeFocusOnTab: true
+                    acceptedButtons: Qt.LeftButton | Qt.MiddleButton
                     onClicked: mouse => {
+                        if (mouse.button === Qt.MiddleButton) {
+                            const winIds = desktop.windowIds();
+                            if (effectWatcher.registered && winIds.length > 0) {
+                                root.activateWindowView(winIds);
+                            }
+                            return;
+                        }
                         pagerModel.changePage(desktop.index);
                     }
                     Accessible.name: Plasmoid.configuration.displayedText ? desktop.display : i18nc("@info:whatsthis Accessible name for pager section", "Desktop %1", (desktop.index + 1))
@@ -483,6 +518,7 @@ PlasmoidItem {
                             readonly property bool minimized: model.IsMinimized
                             readonly property bool isActive: model.IsActive
                             readonly property int stackingOrder: model.PagerStackingOrder
+                            readonly property var winIdList: model.WinIdList
                         }

                         delegate: WindowDelegate {
-- 
